void dei_temp_usr_irq (void)
{    
	dei_temp_rx_irq();
	
	if( dei_temp_vars.rx_error )
	{
		dei_temp_vars.rx_error = FALSE ; 

		if( dei_temp_vars.rx_err_count == DEI_TEMP_ERR_MAX )
        {
            set_temp_sensor_present(FALSE);  

            TRACE_DEI_TEMP("[DEI_TEMP_SENSOR_NOT_PRESENT]\n\r");      
        }
        else
        {
            dei_temp_vars.rx_err_count ++ ;

            TRACE_DEI_TEMP("[DEI_TEMP_SENSOR_ERROR]\n\r");      
        }

        wake_ck_leave();					              
	}	

	if( dei_temp_vars.rx_complete )
	{
		dei_temp_vars.rx_complete = FALSE ; 
				
		set_temp_sensor_present(TRUE);

        set_temp_sensor_value(dei_temp_cast(dei_temp_vars.rx_data));
                    
        dei_temp_vars.rx_err_count = 0 ;

        dei_temp_vars.rx_data     = 0 ; 
		dei_temp_vars.rx_idx      = 0 ;
				
		wake_ck_leave();
	}	
} 

